############################################################
# Generate Final Analysis Summary
#
# Project:
#   Gastric Cancer EMT–TME Analysis
#
# Dataset:
#   GSE183904
#
# External validation:
#   TCGA-STAD
#
# Purpose:
#   Collect key outputs generated by scripts 01–08 and
#   produce concise, machine-readable and human-readable
#   summaries for the GitHub repository.
#
# This script DOES NOT perform new biological analyses.
# It only summarizes completed upstream analyses.
#
# Main outputs:
#
#   results/summary/
#     01_dataset_overview.csv
#     02_cell_type_composition.csv
#     03_sample_status_composition.csv
#     04_EMT_state_summary.csv
#     05_EMT_rank_summary.csv
#     06_trajectory_summary.csv
#     07_trajectory_modules.csv
#     08_NicheNet_top_ligands.csv
#     09_NicheNet_top_TFs.csv
#     10_lncRNA_summary.csv
#     11_high_confidence_lncRNAs.csv
#     12_TCGA_survival_summary.csv
#     13_TCGA_Cox_results.csv
#     14_pipeline_output_manifest.csv
#     analysis_summary.txt
#     analysis_summary.md
############################################################


# ==========================================================
# 0. Required packages
# ==========================================================

required_packages <- c(
  "Seurat",
  "dplyr"
)


missing_packages <- required_packages[
  !vapply(
    required_packages,
    requireNamespace,
    quietly = TRUE,
    FUN.VALUE = logical(1)
  )
]


if (length(missing_packages) > 0) {
  
  stop(
    paste0(
      "\nMissing required packages:\n",
      paste(
        missing_packages,
        collapse = ", "
      ),
      "\n"
    ),
    call. = FALSE
  )
  
}


suppressPackageStartupMessages({
  
  library(Seurat)
  library(dplyr)
  
})


