# ==========================================================
# 3. Helper functions
# ==========================================================

log_message <- function(...) {
  
  cat(
    format(
      Sys.time(),
      "[%Y-%m-%d %H:%M:%S]"
    ),
    ...,
    "\n"
  )
  
}


checkpoint <- function(
    condition,
    message
) {
  
  if (!condition) {
    
    stop(
      message,
      call. = FALSE
    )
    
  }
  
}


read_csv_safe <- function(
    file_path,
    required = TRUE
) {
  
  if (!file.exists(file_path)) {
    
    if (required) {
      
      stop(
        paste0(
          "Required file not found:\n",
          file_path
        ),
        call. = FALSE
      )
      
    } else {
      
      return(
        NULL
      )
      
    }
    
  }
  
  
  read.csv(
    file_path,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )
  
}


write_summary_csv <- function(
    object,
    filename
) {
  
  output_file <- file.path(
    summary_dir,
    filename
  )
  
  
  write.csv(
    object,
    output_file,
    row.names = FALSE
  )
  
  
  log_message(
    "Saved:",
    output_file
  )
  
  
  output_file
  
}


safe_percent <- function(
    numerator,
    denominator
) {
  
  if (
    denominator == 0
  ) {
    
    return(
      NA_real_
    )
    
  }
  
  
  100 * numerator / denominator
  
}


