# ==========================================================
# 25. Obtain key EMT counts
# ==========================================================

get_count <- function(
    table_object,
    group_column,
    group_value,
    count_column = "cell_count"
) {
  
  index <- as.character(
    table_object[
      [group_column]
    ]
  ) ==
    group_value
  
  
  if (
    !any(
      index
    )
  ) {
    
    return(
      0
    )
    
  }
  
  
  table_object[
    [count_column]
  ][
    which(
      index
    )[1]
  ]
  
}


