get_metric_value <- function(
    summary_table,
    metric_name
) {
  
  if (
    !all(
      c(
        "metric",
        "value"
      ) %in%
      colnames(
        summary_table
      )
    )
  ) {
    
    return(
      NA
    )
    
  }
  
  
  index <- summary_table$metric ==
    metric_name
  
  
  if (
    !any(
      index
    )
  ) {
    
    return(
      NA
    )
    
  }
  
  
  summary_table$value[
    which(
      index
    )[1]
  ]
  
}


tcga_patients <- get_metric_value(
  
  tcga_summary,
  
  "TCGA patients with expression and OS"
  
)


tcga_events <- get_metric_value(
  
  tcga_summary,
  
  "OS events"
  
)


tcga_candidate_count <- get_metric_value(
  
  tcga_summary,
  
  "Candidate lncRNAs tested by Cox"
  
)


